import Phaser from "phaser";
import interactions from "../../assets/data/interactions.json";
import questsData from "../../assets/data/quests.json";

const TILE = 4;
const MAP_W = 600;
const MAP_H = 400;
const WORLD_W = MAP_W * TILE;
const WORLD_H = MAP_H * TILE;

// Terrain types
const T = {
  GRASS: 0,
  ROAD: 1,
  WATER: 2,
  BRIDGE: 3,
  TREE: 4,
  ROCK: 5,
  WALL: 6,
  FLOOR: 7,
  DOOR: 8,
};

function isPassableType(t) {
  return (
    t === T.GRASS ||
    t === T.ROAD ||
    t === T.BRIDGE ||
    t === T.FLOOR ||
    t === T.DOOR
  );
}

function blocksLightType(t) {
  return t === T.TREE || t === T.ROCK || t === T.WALL;
}

function isFeatureType(t) {
  return t === T.TREE || t === T.ROCK || t === T.WALL || t === T.WATER;
}

function getTileVariant(x, y, terrain, closedDoors, questHighlight) {
  const hash = (x * 7 + y * 13) | 0;
  const doorKey = `${x},${y}`;
  if (terrain === T.DOOR && closedDoors?.has(doorKey)) {
    return 18 + (Math.abs(hash) % 2);
  }
  if (questHighlight) {
    const key = `${x},${y}`;
    if (questHighlight.has(key)) return 20;
    if (questHighlight.has(`n:${key}`)) return 21;
  }
  switch (terrain) {
    case T.GRASS:
      return (x + y) % 3;
    case T.ROAD:
      return 3 + (Math.abs(hash) % 2);
    case T.WATER:
      return 5 + (Math.abs(hash) % 2);
    case T.BRIDGE:
      return 7 + ((x * 3 + y * 5) % 2);
    case T.TREE:
      return 9 + (Math.abs(hash) % 3);
    case T.ROCK:
      return 12 + (Math.abs(hash) % 2);
    case T.WALL:
      return 14 + (Math.abs(hash) % 2);
    case T.FLOOR:
      return 16;
    case T.DOOR:
      return 17;
    default:
      return 0;
  }
}

// ── Quest State Management ────────────────────────────────────────────

function getQuestById(id, data) {
  for (const key of Object.keys(data.quests)) {
    if (key === id || data.quests[key].id === id)
      return { quest: data.quests[key], key };
  }
  return null;
}

function getStageById(questId, stageId, data) {
  const quest = getQuestById(questId, data);
  if (!quest) return null;
  for (const stage of quest.quest.stages) {
    if (stage.id === stageId) return stage;
  }
  return null;
}

function getQuestObject(questId, data) {
  const quest = getQuestById(questId, data);
  return quest ? quest.quest : null;
}

