  updateQuestPanel() {
    if (!this.questList) return;
    let html = "";
    const sSection =
      "color:#88ccff;font-size:12px;margin-top:4px;margin-bottom:2px;";
    const sItem = "color:#ccddcc;font-size:12px;line-height:1.2;";
    const sStatus = "color:#667788;font-size:10px;";
    const active = Object.keys(this.acceptedQuests).filter(
      (qid) => !this.completedQuests[qid] && this.activeQuests[qid],
    );
    if (active.length > 0) {
      html += `<div style="${sSection}">ACTIVE QUESTS</div>`;
      for (const qid of active) {
        const entry = this.activeQuests[qid];
        const quest = this.quests.quests[qid];
        const stage = quest.stages[entry.stageIndex];
        html += `<div style="${sItem}">${quest.name} — ${stage.name}</div>`;
        for (const [oid, completed] of Object.entries(entry.objectives)) {
          const obj = stage.objectives.find((o) => o.id === oid);
          if (obj) {
            const mark = completed ? "✓" : " ";
            html += `<div style="${sStatus}">[${mark}] ${obj.text}</div>`;
          }
        }
      }
    } else {
      html += `<div style="${sSection}">ACTIVE QUESTS</div>`;
      html += `<div style="${sStatus}">No active quests</div>`;
    }
    const completed = Object.keys(this.completedQuests);
    if (completed.length > 0) {
      html += `<div style="${sSection}">COMPLETED</div>`;
      for (const qid of completed) {
        const quest = this.quests.quests[qid];
        html += `<div style="${sItem}">${quest.name}</div>`;
      }
    }
    this.questList.innerHTML = html;
  }

  showQuestPanel() {
    if (this.questPanelEl) {
      this.updateQuestPanel();
      this.questPanelEl.setVisible(true);
      this.questPanelVisible = true;
    }
  }

  hideQuestPanel() {
    if (this.questPanelEl) {
      this.questPanelEl.setVisible(false);
      this.questPanelVisible = false;
    }
  }

