import Phaser from "phaser";

export class MenuScene extends Phaser.Scene {
  constructor() {
    super("MenuScene");
  }

  create() {
    const { width, height } = this.scale;
    const cx = width / 2;
    const cy = height / 2;

    // Deep forest gradient background
    const bg = this.add.graphics();
    for (let y = 0; y < height; y++) {
      const t = y / height;
      const r = Math.floor(Phaser.Math.Linear(8, 18, t));
      const g = Math.floor(Phaser.Math.Linear(12, 35, t));
      const b = Math.floor(Phaser.Math.Linear(20, 22, t));
      bg.fillStyle(Phaser.Display.Color.GetColor(r, g, b));
      bg.fillRect(0, y, width, 1);
    }

    // Distant trees silhouette
    this.drawForestSilhouette(cx, height);

    // Floating particles (fireflies / spores)
    this.particles = [];
    for (let i = 0; i < 40; i++) {
      const p = this.add.circle(
        Phaser.Math.Between(0, width),
        Phaser.Math.Between(0, height),
        Phaser.Math.Between(1, 2),
        0x88cc66,
        Phaser.Math.FloatBetween(0.1, 0.5),
      );
      this.particles.push({
        sprite: p,
        speedX: Phaser.Math.FloatBetween(-0.15, 0.15),
        speedY: Phaser.Math.FloatBetween(-0.3, -0.05),
        baseAlpha: p.alpha,
        phase: Phaser.Math.FloatBetween(0, Math.PI * 2),
      });
    }

    // Title page text as a DOM element (crisp, easy styling)
    const box = document.createElement("div");
    box.id = "title-screen";
    box.innerHTML = `
      <div class="title-frame">
        <span class="corner-tr"></span>
        <span class="corner-br"></span>
        <h1 id="title">A Short Walk</h1>
        <div id="subtitle">~ in which, nothing much happens ~</div>
        <div id="prompt">[ Press SPACE to Start ]</div>
      </div>
    `;
    const titleEl = this.add.dom(cx, cy, box);
    titleEl.setScale(0.5);

    // Blink the prompt
    const promptEl = box.querySelector("#prompt");
    this.tweens.add({
      targets: promptEl,
      alpha: { from: 1, to: 0.3 },
      duration: 800,
      yoyo: true,
      repeat: -1,
      ease: "Sine.easeInOut",
    });

    // Input
    this.input.keyboard.once("keydown-SPACE", () => this.startGame());
  }

  drawForestSilhouette(cx, height) {
    const trees = this.add.graphics();
    const width = this.scale.width;
    trees.fillStyle(0x0d1a0d, 1);

    const baseY = height - 30;

    // Layer of tree shapes
    for (let i = 0; i < 18; i++) {
      const x = Phaser.Math.Between(-10, width + 10);
      const treeH = Phaser.Math.Between(30, 80);
      const trunkW = Phaser.Math.Between(2, 5);
      const canopyR = Phaser.Math.Between(8, 20);

      // Trunk
      trees.fillRect(x - trunkW / 2, baseY - treeH, trunkW, treeH);

      // Canopy (triangle layers)
      for (let layer = 0; layer < 3; layer++) {
        const layerY = baseY - treeH + layer * (canopyR * 0.5);
        const layerR = canopyR - layer * 10;
        trees.fillTriangle(
          x,
          layerY - canopyR * 0.6,
          x - layerR,
          layerY + canopyR * 0.3,
          x + layerR,
          layerY + canopyR * 0.3,
        );
      }
    }

    // Ground
    trees.fillRect(0, baseY + 10, width, 20);
  }

  startGame() {
    this.cameras.main.fadeOut(500, 10, 10, 15);
    this.cameras.main.once("camerafadeoutcomplete", () => {
      this.scene.start("WorldScene");
    });
  }

  update(_time, delta) {
    const { width, height } = this.scale;
    for (const p of this.particles) {
      p.phase += delta * 0.001;
      p.sprite.x += p.speedX;
      p.sprite.y += p.speedY;
      p.sprite.alpha = p.baseAlpha * (0.5 + 0.5 * Math.sin(p.phase));

      if (p.sprite.y < -10) {
        p.sprite.y = height + 10;
        p.sprite.x = Phaser.Math.Between(0, width);
      }
      if (p.sprite.x < -10) p.sprite.x = width + 10;
      if (p.sprite.x > width + 10) p.sprite.x = -10;
    }
  }
}
